using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;
namespace ParkingLotEnvironment.CloudPilot {
public static class PorterImport {
 [Serializable]class Record{public string name,file;public int vertexCount,indexCount,material;}
 [Serializable]class Model{public string name;public Record[] meshes;public string[] materials;}
 public static GameObject Create(Transform parent){string w=ContextBuilder.W;var data=JsonUtility.FromJson<Model>(File.ReadAllText(w+"/PorterData/porter.json"));var go=new GameObject("Hyundai_Porter_II_max7th");go.transform.SetParent(parent,false);var mats=new Dictionary<string,Material>();
  foreach(var name in data.materials){var m=new Material(Shader.Find("Standard")){name="Porter_"+name};m.SetFloat("_Metallic",.05f);m.SetFloat("_Glossiness",.38f);switch(name){case "BluePaint":m.color=new Color(.07f,.20f,.39f);m.SetFloat("_Metallic",.18f);m.SetFloat("_Glossiness",.68f);break;case "Glass":m.shader=Shader.Find("ParkingLot/Realism20261104/Glass");if(!m.shader)m.shader=Shader.Find("Standard");m.color=new Color(.018f,.03f,.042f,.9f);m.SetFloat("_Glossiness",.94f);m.SetFloat("_Metallic",.3f);break;case "Rubber":m.color=new Color(.055f,.059f,.063f);m.SetFloat("_Glossiness",.18f);break;case "Steel":m.color=new Color(.42f,.45f,.47f);m.SetFloat("_Metallic",.72f);m.SetFloat("_Glossiness",.42f);break;case "DarkTrim":m.color=new Color(.055f,.065f,.074f);m.SetFloat("_Glossiness",.24f);break;case "Headlight":m.color=new Color(.54f,.61f,.66f);m.SetFloat("_Metallic",.55f);m.SetFloat("_Glossiness",.91f);break;case "RedLens":m.color=new Color(.35f,.015f,.02f);m.SetFloat("_Glossiness",.85f);break;case "AmberLens":m.color=new Color(.65f,.25f,.025f);m.SetFloat("_Glossiness",.85f);break;}AssetDatabase.CreateAsset(m,w+"/"+m.name+".mat");mats[name]=m;}
  foreach(var item in data.meshes){var mesh=new Mesh{name="Porter_"+item.name,indexFormat=IndexFormat.UInt32};var vv=new Vector3[item.vertexCount];var nn=new Vector3[item.vertexCount];var uv=new Vector2[item.vertexCount];var indices=new int[item.indexCount];using(var r=new BinaryReader(File.OpenRead(w+"/PorterData/"+item.file))){for(int i=0;i<vv.Length;i++){vv[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());nn[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());}for(int i=0;i<indices.Length;i++)indices[i]=(int)r.ReadUInt32();}mesh.vertices=vv;mesh.normals=nn;mesh.uv=uv;mesh.triangles=indices;mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,w+"/"+mesh.name+".asset");var part=new GameObject(item.name);part.transform.SetParent(go.transform,false);part.AddComponent<MeshFilter>().sharedMesh=mesh;var mr=part.AddComponent<MeshRenderer>();mr.sharedMaterial=mats[item.name];mr.shadowCastingMode=ShadowCastingMode.On;mr.receiveShadows=true;mr.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;GameObjectUtility.SetStaticEditorFlags(part,StaticEditorFlags.ReflectionProbeStatic);}
  // Tail lamps and Korean plates are actual geometry, outside the intact cabin mesh.
  foreach(float x in new[]{-.67f,.67f}){Box(go.transform,"RearLampHousing",new Vector3(x,.52f,-2.60f),new Vector3(.32f,.16f,.06f),mats["DarkTrim"]);Box(go.transform,"RearRedLens",new Vector3(x-.045f,.52f,-2.638f),new Vector3(.19f,.12f,.025f),mats["RedLens"]);Box(go.transform,"RearIndicator",new Vector3(x+.10f,.52f,-2.638f),new Vector3(.07f,.12f,.025f),mats["AmberLens"]);}
  var plateMat=new Material(Shader.Find("Standard")){name="Porter_KoreanNumberPlate",color=Color.white};plateMat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(w+"/PorterPlate.png");plateMat.SetFloat("_Glossiness",.3f);AssetDatabase.CreateAsset(plateMat,w+"/Porter_KoreanNumberPlate.mat");foreach(int sign in new[]{-1,1}){var q=GameObject.CreatePrimitive(PrimitiveType.Quad);q.name="KoreanPlate";q.transform.SetParent(go.transform,false);q.transform.localPosition=new Vector3(0,.48f,sign>0?2.49f:-2.65f);q.transform.localRotation=Quaternion.Euler(0,sign>0?180:0,0);q.transform.localScale=new Vector3(.52f,.11f,1);UnityEngine.Object.DestroyImmediate(q.GetComponent<Collider>());q.GetComponent<Renderer>().sharedMaterial=plateMat;}
  PrefabUtility.SaveAsPrefabAsset(go,w+"/HyundaiPorterII_Blue.prefab");return go;
 }
 static void Box(Transform parent,string name,Vector3 p,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=size;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=m;}
}}
